// ─── File: SpinLockDemo.java ───
// Runnable demo. In a real project each class lives in its own file.
package com.bank.sequencer;

import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class SpinLockDemo {
    private static final Logger LOG = Logger.getLogger("Sequencer");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        TradeSequencer sequencer = new TradeSequencer();
        int threads = 4, perThread = 5;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        List<Future<List<Long>>> futures = new ArrayList<>();

        for (int t = 0; t < threads; t++) {
            futures.add(pool.submit(() -> {
                List<Long> seqs = new ArrayList<>();
                for (int i = 0; i < perThread; i++) seqs.add(sequencer.next("RELIANCE"));
                return seqs;
            }));
        }

        Set<Long> all = new TreeSet<>();
        for (Future<List<Long>> f : futures) all.addAll(f.get());
        LOG.info(() -> "assigned " + all.size() + " unique sequence numbers (expected "
            + (threads * perThread) + ")");
        LOG.info(() -> "max sequence = " + Collections.max(all));
        pool.shutdown();
    }
}

// ─── Would be in lock/SpinLock.java ───
class SpinLock {
    private final java.util.concurrent.atomic.AtomicBoolean locked =
        new java.util.concurrent.atomic.AtomicBoolean(false);

    void lock() {
        while (!locked.compareAndSet(false, true)) {  // CAS free→held
            Thread.onSpinWait();                      // Java 9 hint: spin-wait (PAUSE on x86)
        }
    }
    void unlock() { locked.set(false); }
}

// ─── Would be in core/TradeSequencer.java ───
class TradeSequencer {
    private final SpinLock lock = new SpinLock();
    private long sequence = 0;        // guarded by the spin lock

    // Critical section is TINY — a single increment — so spinning is ideal.
    long next(String symbol) {
        lock.lock();
        try {
            return ++sequence;        // strictly increasing, no gaps
        } finally {
            lock.unlock();
        }
    }
}
```

