// ─── File: src/test/java/com/bank/sequencer/core/TradeSequencerTest.java ───
package com.bank.sequencer.core;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class TradeSequencerTest {
    @Test
    void sequenceNumbersAreUniqueUnderContention() throws Exception {
        TradeSequencer seq = new TradeSequencer();
        int threads = 8, per = 1000;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        Set<Long> seen = ConcurrentHashMap.newKeySet();
        CountDownLatch done = new CountDownLatch(threads);
        for (int t = 0; t < threads; t++)
            pool.submit(() -> { for (int i = 0; i < per; i++) seen.add(seq.next("X")); done.countDown(); });
        assertTrue(done.await(5, TimeUnit.SECONDS));
        assertEquals(threads * per, seen.size());   // no duplicates, no lost updates
        pool.shutdown();
    }
}
